def normalize_dushi_bibliography_name(raw_name: str) -> str:
    name = raw_name.strip(" \t\r\n　：:，,、。；;（）()《》“”\"'")
    name = DUSHI_BIBLIOGRAPHY_ALIASES.get(name, name)
    changed = True
    stripped_role = False
    while changed:
        changed = False
        for suffix in DUSHI_BIBLIOGRAPHY_ROLE_SUFFIXES:
            if name.endswith(suffix) and len(name) > len(suffix) + 1:
                name = name[:-len(suffix)].strip()
                name = DUSHI_BIBLIOGRAPHY_ALIASES.get(name, name)
                stripped_role = True
                changed = True
                break
    if stripped_role:
        for dynasty in sorted(DUSHI_BIBLIOGRAPHY_DYNASTIES, key=len, reverse=True):
            if name.startswith(dynasty) and len(name) > len(dynasty) + 1:
                name = name[len(dynasty):]
                break
    return DUSHI_BIBLIOGRAPHY_ALIASES.get(name, name)


def looks_like_dushi_bibliography_author(name: str) -> bool:
    if not name or len(name) < 2 or len(name) > 5:
        return False
    if name in DUSHI_BIBLIOGRAPHY_SKIP_NAMES or name in STOP_NAMES:
        return False
    if any(fragment in name for fragment in DUSHI_BIBLIOGRAPHY_BAD_FRAGMENTS):
        return False
    if name.endswith(("集", "表", "目", "法", "记略", "诗钞", "文集", "诗集")):
        return False
    return True


def iter_dushi_bibliography_authors(text: str):
    seen: set[tuple[str, str]] = set()
    for line in text.splitlines():
        if "：" not in line:
            continue
        stripped_line = line.strip()
        for match in DUSHI_BIBLIOGRAPHY_AUTHOR_RE.finditer(line):
            segment = match.group(1)
            segment = re.sub(r"（[^）]*）", "、", segment)
            segment = re.sub(r"\([^)]*\)", "、", segment)
            segment = DUSHI_BIBLIOGRAPHY_INNER_DYNASTY_RE.sub(lambda item: f"{item.group(1)}、", segment)
            for part in DUSHI_BIBLIOGRAPHY_SPLIT_RE.split(segment):
                part = part.strip(" \t\r\n　：:，,、。；;（）()《》“”\"'")
                if not part:
                    continue
                for candidate in DUSHI_BIBLIOGRAPHY_CANDIDATE_RE.findall(part):
                    name = normalize_dushi_bibliography_name(candidate)
                    if not looks_like_dushi_bibliography_author(name):
                        continue
                    key = (name, stripped_line)
                    if key in seen:
                        continue
                    seen.add(key)
                    yield name, stripped_line[:180]


def add_dushi_bibliography_author_hits(
    text: str,
    people: dict[str, PersonHit],
    collection: str,
    book: str,
    chapter: str,
) -> None:
    if not is_dushi_bibliography_chapter(book, chapter):
        return
    for raw_name, ctx in iter_dushi_bibliography_authors(text):
        name = canonical_name(raw_name, ctx, book, chapter)
        if name in BOOK_SKIP_NAMES.get(book, set()) or name in STOP_NAMES:
            continue
        category = "source_author"
        score = 6
        hit = people.setdefault(name, PersonHit(name=name))
        hit.occurrences += 1
        hit.relevant_occurrences += 1
        hit.name_signals += 1
        hit.strong_signals += 1
        hit.score += score
        hit.categories[category] += 1
        hit.books[book] += 1
        hit.collections[collection] += 1
        hit.chapters[f"{book} / {chapter}"] += 1
        hit.cue_hits["书目作者表"] += 1
        add_evidence(
            hit,
            {
                "book": book,
                "collection": collection,
                "chapter": chapter,
                "category": category,
                "score": score,
                "cues": ["书目作者表"],
                "snippet": ctx,
                "curated": name in CURATED_IDENTITIES,
            },
        )


def extract_from_text(
    text: str,
    path: Path,
    source_root: Path,
    people: dict[str, PersonHit],
    title_names: set[str],
) -> None:
    collection, book, chapter = meta_for_path(source_root, path)
    title_names = extract_title_names_from_strings((book, chapter))
    seen_matches: set[tuple[int, int, str]] = set()
    for regex in (NAME_RE, FOREIGN_RE, NONSTANDARD_NAME_RE):
        for match in regex.finditer(text):
            name = match.group(0)
            if not is_likely_person_name(name):
                continue
            if is_contextual_false_positive(name, text, match.start(), match.end()):
                continue
            raw_name = name
            if raw_name == "爱神" and text[match.end(): match.end() + 3] == "邱比特":
                continue
            if raw_name == "导群" and match.start() and text[match.start() - 1: match.start()] == "领":
                continue
            if raw_name == "湘女" and match.start() and text[match.start() - 1: match.start()] in SINGLE_SURNAMES:
                continue
            if raw_name == "马偕" and book == "李敖五五日记":
                continue
            if raw_name == "李杰" and book == "李敖Talk秀" and text[match.end(): match.end() + 1] == "圣":
                continue
            if raw_name == "阿里" and book == "李敖Talk秀" and text[match.end(): match.end() + 1] in {"斯", "山"}:
                continue
            ctx = context_window(text, match.start(), match.end())
            name = canonical_name(name, ctx, book, chapter)
            if name in BOOK_SKIP_NAMES.get(book, set()) or name in STOP_NAMES:
                continue
            if name == "周至柔" and "天下至柔莫如水" in ctx:
                continue
            if name == "汪汪" and book != "李敖的情诗":
                continue
            if name == "万劫" and book != "上山·上山·爱":
                continue
            if name in {"龙头", "史处长", "余三共", "华老师", "欧卡曾", "王九胆", "胡牧师", "王家法", "老黄", "士官长", "班长"} and book != "红色11":
                continue
            if name in {"校长", "局长", "陈教授"}:
                continue
            if name in {"吴先生", "她爸爸", "作家大学生的妈妈", "外婆", "大阿姨", "三娘子"}:
                continue
            match_key = (match.start(), match.end(), name)
            if match_key in seen_matches:
                continue
            seen_matches.add(match_key)
            after = text[match.end(): match.end() + 6]
            before = text[match.start() - 1: match.start()] if match.start() else ""
            pre12 = text[max(0, match.start() - 12): match.start()]
            has_name_signal = (
                name in title_names
                or name in FOREIGN_AND_HISTORICAL
                or before in SIGNAL_BEFORE
                or (after[:1] in SIGNAL_AFTER)
                or any(after.startswith(suffix) for suffix in ROLE_SUFFIXES)
            )
            has_strong_signal = (
                name in title_names
                or name in FOREIGN_AND_HISTORICAL
                or any(after.startswith(suffix) for suffix in ROLE_SUFFIXES)
                or any(pre12.endswith(prefix) for prefix in DIRECT_PREFIXES)
                or any(after.startswith(verb) for verb in POST_VERBS)
                or bool(ROLE_PREFIX_RE.search(pre12))
            )
            if is_dushi_bibliography_chapter(book, chapter):
                category, score, cues = "mentioned", 0, []
            else:
                category, score, cues = score_context(name, ctx, after)
            hit = people.setdefault(name, PersonHit(name=name))
            hit.occurrences += 1
            if has_name_signal:
                hit.name_signals += 1
            if has_strong_signal:
                hit.strong_signals += 1
            hit.score += score
            hit.categories[category] += 1
            hit.books[book] += 1
            hit.collections[collection] += 1
            hit.chapters[f"{book} / {chapter}"] += 1
            if name in title_names:
                hit.title_hits += 1
                score += 2
            if score > 0 or name in title_names or name in CURATED_IDENTITIES:
                hit.relevant_occurrences += 1
                for cue in cues:
                    hit.cue_hits[cue] += 1
                add_evidence(
                    hit,
                    {
                        "book": book,
                        "collection": collection,
                        "chapter": chapter,
                        "category": category,
                        "score": score,
                        "cues": cues[:6],
                        "snippet": ctx,
                        "curated": name in CURATED_IDENTITIES,
                    },
                )

    add_dushi_bibliography_author_hits(text, people, collection, book, chapter)

    for phrase, targets in BOOK_PHRASE_PEOPLE.get(book, {}).items():
        start = 0
        while True:
            idx = text.find(phrase, start)
            if idx < 0:
                break
            ctx = context_window(text, idx, idx + len(phrase))
            for target in targets:
                categories = CURATED_IDENTITIES.get(target, ["mentioned"])
                category = categories[0]
                score = 6
                hit = people.setdefault(target, PersonHit(name=target))
                hit.occurrences += 1
                hit.relevant_occurrences += 1
                hit.name_signals += 1
                hit.strong_signals += 1
                hit.score += score
                hit.categories[category] += 1
                hit.books[book] += 1
                hit.collections[collection] += 1
                hit.chapters[f"{book} / {chapter}"] += 1
                hit.cue_hits[phrase] += 1
                add_evidence(
                    hit,
                    {
                        "book": book,
                        "collection": collection,
                        "chapter": chapter,
                        "category": category,
                        "score": score,
                        "cues": [phrase],
                        "snippet": ctx,
                        "curated": target in CURATED_IDENTITIES,
                    },
                )
            start = idx + len(phrase)


def extract_title_names_from_strings(raw_titles: tuple[str, ...] | list[str]) -> set[str]:
    names: set[str] = set()
    for raw in raw_titles:
        for match in NAME_RE.finditer(raw):
            name = match.group(0)
            if is_likely_person_name(name):
                names.add(ALIASES.get(name, name))
        for match in FOREIGN_RE.finditer(raw):
            names.add(ALIASES.get(match.group(0), match.group(0)))
        for match in NONSTANDARD_NAME_RE.finditer(raw):
            names.add(ALIASES.get(match.group(0), match.group(0)))
        for marker in ("研究", "评传", "真面目", "臭史", "论"):
            if marker in raw:
                prefix = raw.split(marker, 1)[0]
                for match in NAME_RE.finditer(prefix):
                    name = match.group(0)
                    if is_likely_person_name(name):
                        names.add(ALIASES.get(name, name))
    return names


def extract_title_names(source_root: Path, files: list[Path] | None = None) -> set[str]:
    names: set[str] = set()
    for path in files or iter_text_files(source_root):
        _collection, book, chapter = meta_for_path(source_root, path)
        names.update(extract_title_names_from_strings((book, chapter)))
    return names


def keep_person(hit: PersonHit) -> bool:
    if hit.name == "班长" and "红色11" in hit.books:
        return True
    if hit.name == "大风" and "李敖书序集" in hit.books:
        return True
    if hit.name in STOP_NAMES:
        return False
    if hit.name in CURATED_IDENTITIES and hit.occurrences > 0:
        return True
    if hit.title_hits > 0:
        return True
    if hit.name_signals == 0:
        return False
    if hit.strong_signals >= 1 and hit.relevant_occurrences >= 1:
        return True
    if hit.name in FOREIGN_AND_HISTORICAL and hit.occurrences >= 1:
        return True
    if hit.name in FICTIONAL_CHARACTERS and hit.occurrences >= 1:
        return True
    if hit.strong_signals >= 2 and hit.occurrences >= 2:
        return True
    return False


def categories_for_hit(hit: PersonHit) -> list[str]:
    if hit.name in CURATED_IDENTITIES:
        return CURATED_IDENTITIES[hit.name]
    if hit.name in FICTIONAL_CHARACTERS:
        return ["fictional"]
    if hit.name in SPIRITUAL_ONLY:
        return ["spiritual"]
    categories = []
    minimum = max(2, math.ceil(hit.occurrences * 0.08))
    for category, count in hit.categories.most_common():
        if category == "mentioned" and len(hit.categories) > 1:
            continue
        if category == "source_author" or count >= minimum or category == primary_category(hit):
            categories.append(category)
    if hit.name in FOREIGN_AND_HISTORICAL and "spiritual" not in categories:
        categories.append("spiritual")
    if hit.name in FICTIONAL_CHARACTERS and "fictional" not in categories:
        categories.append("fictional")
    if not categories:
        categories.append("mentioned")
    return categories


def primary_category(hit: PersonHit) -> str:
    if hit.name in CURATED_IDENTITIES:
        return CURATED_IDENTITIES[hit.name][0]
    if hit.name in FICTIONAL_CHARACTERS:
        return "fictional"
    if hit.name in SPIRITUAL_ONLY:
        return "spiritual"
    weighted = Counter(hit.categories)
    if hit.name in FOREIGN_AND_HISTORICAL:
        weighted["spiritual"] += 4
    if hit.relevant_occurrences == 0:
        return "mentioned"
    if weighted.get("source_author") and weighted.most_common(1)[0][0] == "mentioned":
        return "source_author"
    return weighted.most_common(1)[0][0]


def confidence(hit: PersonHit) -> int:
    points = 30
    points += min(hit.relevant_occurrences * 8, 30)
    points += min(len(hit.books) * 4, 20)
    points += min(hit.title_hits * 10, 20)
    points += min(hit.strong_signals * 6, 18)
    points += min(hit.score, 25)
    return max(1, min(points, 99))


def aliases_for_person(name: str) -> list[str]:
    extra_aliases = {
        "李家大小姐": {"湘女"},
        "咪咪": {"涂咪咪"},
        "娟娟（军中乐园）": {"娟娟", "娟娟小姐"},
    }
    return sorted(
        {
            alias
            for alias, target in ALIASES.items()
            if target == name and alias != name and alias not in STOP_NAMES
        } | extra_aliases.get(name, set())
    )


def normalize_evidence_items(hit: PersonHit, cats: list[str]) -> list[dict]:
    normalized = []
    allowed = set(cats)
    fallback = primary_category(hit)
    cue_map = {
        "meeting": MEETING_CUES,
        "correspondence": CORRESPONDENCE_CUES,
        "teacher_student": TEACHER_STUDENT_CUES,
        "classmate": CLASSMATE_CUES,
        "colleague": COLLEAGUE_CUES,
        "editor": EDITOR_CUES,
        "friendship": FRIENDSHIP_CUES,
        "family": FAMILY_CUES,
        "in_law": IN_LAW_CUES,
        "romance": ROMANCE_CUES,
        "property_finance": PROPERTY_FINANCE_CUES,
        "public_funds": PUBLIC_FUNDS_CUES,
        "trust_property": TRUST_PROPERTY_CUES,
        "witness": WITNESS_CUES,
        "publishing": PUBLISHING_CUES,
        "academic": ACADEMIC_CUES,
        "academic_admin": ACADEMIC_ADMIN_CUES,
        "media": MEDIA_CUES,
        "military_student": ("入营", "军事学校", "军中学校", "学生", "在校", "退学"),
        "legal_official": LEGAL_OFFICIAL_CUES,
        "lawyer_counsel": LAWYER_COUNSEL_CUES,
        "litigation": LITIGATION_CUES,
        "politician": POLITICIAN_CUES,
        "intelligence_police": INTELLIGENCE_POLICE_CUES,
        "military_figure": MILITARY_FIGURE_CUES,
        "party_propaganda": PARTY_PROPAGANDA_CUES,
        "institutional_security": INSTITUTIONAL_SECURITY_CUES,
        "public_debate": PUBLIC_DEBATE_CUES,
        "spiritual": SPIRITUAL_CUES,
    }
    for item in hit.evidence:
        fixed = dict(item)
        if fixed.get("category") not in allowed:
            snippet = fixed.get("snippet", "")
            scored = [
                (sum(1 for cue in cue_map.get(cat, ()) if cue in snippet), cat)
                for cat in cats
            ]
            scored.sort(reverse=True)
            fixed["category"] = scored[0][1] if scored and scored[0][0] > 0 else fallback
        normalized.append(fixed)
    return normalized


def build_outputs(people: dict[str, PersonHit], source_root: Path, files: list[Path]) -> dict:
    kept = [hit for hit in people.values() if keep_person(hit)]
    kept_names = {hit.name for hit in kept}
    person_rows = []
    identity_links = []
    by_book: dict[str, dict] = {}
    for path in files:
        collection, book, _chapter = meta_for_path(source_root, path)
        by_book.setdefault(book, {"book": book, "collection": collection, "people": Counter(), "chapters": 0})
        by_book[book]["chapters"] += 1

    for hit in kept:
        cats = categories_for_hit(hit)
        primary = primary_category(hit)
        row = {
            "name": hit.name,
            "aliases": aliases_for_person(hit.name),
            "category": primary,
            "categoryLabel": CATEGORY_LABELS[primary],
            "primaryCategory": primary,
            "primaryCategoryLabel": CATEGORY_LABELS[primary],
            "categories": cats,
            "categoryLabels": [CATEGORY_LABELS[cat] for cat in cats],
        "categoryStats": [
                {
                    "category": cat,
                    "label": CATEGORY_LABELS[cat],
                    "count": hit.categories[cat] or max(1, min(hit.occurrences, 3)),
                    "curated": hit.name in CURATED_IDENTITIES,
                }
                for cat in cats
            ],
            "confidence": confidence(hit),
            "occurrences": hit.occurrences,
            "relevantOccurrences": hit.relevant_occurrences,
            "bookCount": len(hit.books),
            "chapterCount": len(hit.chapters),
            "titleHits": hit.title_hits,
            "topBooks": [{"book": b, "count": c} for b, c in hit.books.most_common(12)],
            "topChapters": [{"chapter": ch, "count": c} for ch, c in hit.chapters.most_common(10)],
            "collections": [{"collection": c, "count": n} for c, n in hit.collections.most_common()],
            "cues": [{"cue": cue, "count": n} for cue, n in hit.cue_hits.most_common(10)],
            "evidence": sorted(normalize_evidence_items(hit, cats), key=lambda x: (-x["score"], x["book"], x["chapter"]))[:9],
        }
        person_rows.append(row)
        for stat in row["categoryStats"]:
            identity_links.append(
                {
                    "person": hit.name,
                    "category": stat["category"],
                    "categoryLabel": stat["label"],
                    "count": stat["count"],
                    "personOccurrences": hit.occurrences,
                    "confidence": row["confidence"],
                }
            )
        for book, count in hit.books.items():
            if book in by_book:
                by_book[book]["people"][hit.name] += count

    person_rows.sort(key=lambda x: ("mentioned" in x["categories"], -x["confidence"], -x["occurrences"], x["name"]))
    book_rows = []
    for item in by_book.values():
        people_for_book = item["people"].most_common(80)
        book_rows.append(
            {
                "book": item["book"],
                "collection": item["collection"],
                "chapters": item["chapters"],
                "personCount": len(item["people"]),
                "people": [{"name": name, "count": count} for name, count in people_for_book],
            }
        )
    book_rows.sort(key=lambda x: (x["collection"], x["book"]))

    category_counts = {
        key: sum(1 for x in person_rows if key in x["categories"])
        for key in CATEGORY_LABELS
    }
    totals = {
        "people": len(person_rows),
        "books": len(book_rows),
        "chapters": sum(x["chapters"] for x in book_rows),
        "identityLinks": len(identity_links),
        "personRelations": sum(
            1 for rel in PERSON_RELATIONS if rel["source"] in kept_names and rel["target"] in kept_names
        ),
        "categoryCounts": category_counts,
        "spiritual": category_counts.get("spiritual", 0),
        "fictional": category_counts.get("fictional", 0),
        "legal": category_counts.get("legal_official", 0) + category_counts.get("litigation", 0),
        "direct": category_counts.get("meeting", 0),
        "mentioned": sum(1 for x in person_rows if "mentioned" in x["categories"]),
    }
    return {
        "generatedAt": datetime.now().isoformat(timespec="seconds"),
        "sourceRoot": str(source_root),
        "method": "本地规则抽取：中文姓名候选 + 关系语境线索 + 逐书聚合；结果保留证据片段，适合继续人工校订。",
        "categoryLabels": CATEGORY_LABELS,
        "totals": totals,
        "people": person_rows,
        "identityLinks": sorted(
            identity_links,
            key=lambda x: (-x["personOccurrences"], x["person"], x["category"]),
        ),
        "personRelations": [
            rel for rel in PERSON_RELATIONS if rel["source"] in kept_names and rel["target"] in kept_names
        ],
        "books": book_rows,
    }


def trim_for_site(value: str, limit: int = 180) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if len(text) <= limit:
        return text
    return text[: limit - 1].rstrip() + "…"


def compact_site_data(data: dict) -> dict:
    """Return a lightweight browser payload; people.json keeps the full archive."""
    people = []
    for person in data["people"]:
        people.append(
            {
                "name": person["name"],
                "aliases": person.get("aliases", []),
                "category": person["category"],
                "primaryCategory": person["primaryCategory"],
                "categories": person["categories"],
                "categoryStats": [
                    {
                        "category": stat["category"],
                        "count": stat["count"],
                        "curated": stat.get("curated", False),
                    }
                    for stat in person.get("categoryStats", [])
                ],
                "confidence": person["confidence"],
                "occurrences": person["occurrences"],
                "relevantOccurrences": person["relevantOccurrences"],
                "bookCount": person["bookCount"],
                "chapterCount": person["chapterCount"],
                "cues": person.get("cues", [])[:5],
                "evidence": [
                    {
                        "book": item.get("book", ""),
                        "chapter": item.get("chapter", ""),
                        "snippet": trim_for_site(item.get("snippet", "")),
                        "score": item.get("score", 0),
                        "category": item.get("category", ""),
                    }
                    for item in person.get("evidence", [])[:3]
                ],
            }
        )

    books = []
    for book in data["books"]:
        books.append(
            {
                "book": book["book"],
                "collection": book["collection"],
                "chapters": book["chapters"],
                "personCount": book["personCount"],
                "people": book.get("people", [])[:16],
            }
        )

    return {
        "generatedAt": data["generatedAt"],
        "method": data["method"],
        "categoryLabels": data["categoryLabels"],
        "totals": data["totals"],
        "people": people,
        "personRelations": data.get("personRelations", []),
        "books": books,
    }


PEOPLE_ARCHIVE_SHARD_MAX_BYTES = 8 * 1024 * 1024
PEOPLE_ARCHIVE_SHARD_PREFIX = "people-part-"


def compact_json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def write_people_archive(data: dict, data_dir: Path) -> None:
    """Write the full archive as a small manifest plus people shards."""
    for stale_path in data_dir.glob(f"{PEOPLE_ARCHIVE_SHARD_PREFIX}*.json"):
        stale_path.unlink()

    people_shards = []
    current_people = []
    current_bytes = 2

    def flush_shard() -> None:
        if not current_people:
            return
        part = len(people_shards) + 1
        filename = f"{PEOPLE_ARCHIVE_SHARD_PREFIX}{part:03d}.json"
        shard = {
            "archiveFormat": "people-sharded-v1",
            "generatedAt": data["generatedAt"],
            "part": part,
            "count": len(current_people),
            "people": current_people,
        }
        shard_text = compact_json(shard)
        write_text_lf(data_dir / filename, shard_text)
        people_shards.append(
            {
                "file": filename,
                "count": len(current_people),
                "bytes": len(shard_text.encode("utf-8")),
            }
        )

    for person in data["people"]:
        person_text = compact_json(person)
        person_bytes = len(person_text.encode("utf-8")) + (1 if current_people else 0)
        if current_people and current_bytes + person_bytes > PEOPLE_ARCHIVE_SHARD_MAX_BYTES:
            flush_shard()
            current_people = []
            current_bytes = 2
        current_people.append(person)
        current_bytes += person_bytes
    flush_shard()

    manifest = {
        "archiveFormat": "people-sharded-v1",
        "generatedAt": data["generatedAt"],
        "sourceRoot": data["sourceRoot"],
        "method": data["method"],
        "categoryLabels": data["categoryLabels"],
        "totals": data["totals"],
        "people": {
            "count": len(data["people"]),
            "shards": people_shards,
        },
        "identityLinks": data["identityLinks"],
        "personRelations": data.get("personRelations", []),
        "books": data["books"],
    }
    write_text_lf(data_dir / "people.json", compact_json(manifest))


def write_json_js(data: dict, data_dir: Path) -> None:
    data_dir.mkdir(parents=True, exist_ok=True)
    write_people_archive(data, data_dir)
    js = "window.LEEAO_RELATIONSHIP_DATA = "
    js += compact_json(compact_site_data(data))
    js += ";\n"
    write_text_lf(data_dir / "relationship-data.js", js)


def write_text_lf(path: Path, text: str, encoding: str = "utf-8") -> None:
    tmp_path = path.with_name(f".{path.name}.tmp")
    with tmp_path.open("w", encoding=encoding, newline="\n") as f:
        f.write(text)
    tmp_path.replace(path)


def write_text_exports(data: dict, export_dir: Path) -> None:
    export_dir.mkdir(parents=True, exist_ok=True)
    lines = []
    lines.append("李敖交互式人物关系图：纯文本导出")
    lines.append(f"生成时间：{data['generatedAt']}")
    lines.append(f"来源：{data['sourceRoot']}")
    lines.append(f"说明：{data['method']}")
    lines.append("")
    totals = data["totals"]
    category_summary = "；".join(
        f"{data['categoryLabels'][key]} {count}"
        for key, count in totals.get("categoryCounts", {}).items()
        if count
    )
    lines.append(
        f"总计：{totals['people']} 人；{totals['identityLinks']} 条身份边；"
        f"{totals.get('personRelations', 0)} 条人物关系边；"
        f"{totals['books']} 本书；{totals['chapters']} 个章节。"
    )
    lines.append(f"身份节点：{category_summary}")
    lines.append("")
    if data.get("personRelations"):
        lines.append("==== 人物关系边 ====")
        for rel in data["personRelations"]:
            lines.append(
                f"- 《{rel['book']}》：{rel['source']} -- {rel['relation']} -- {rel['target']}｜"
                f"权重 {rel['weight']}｜{rel['note']}"
            )
        lines.append("")
    for label_key, label in data["categoryLabels"].items():
        group = [p for p in data["people"] if label_key in p["categories"]]
        if not group:
            continue
        lines.append(f"==== {label}（{len(group)}人）====")
        for p in group:
            books = "；".join(f"{b['book']}({b['count']})" for b in p["topBooks"][:6])
            cues = "、".join(c["cue"] for c in p["cues"][:6]) or "无明显线索"
            labels = " / ".join(p["categoryLabels"])
            lines.append(
                f"- {p['name']}｜分类：{labels}｜可信度 {p['confidence']}｜出现 {p['occurrences']} 次｜"
                f"涉及 {p['bookCount']} 本｜线索：{cues}｜主要书目：{books}"
            )
            for ev in p["evidence"][:2]:
                lines.append(f"  证据：《{ev['book']}》/{ev['chapter']}：{ev['snippet']}")
        lines.append("")
    write_text_lf(export_dir / "li-ao-relationships.txt", "\n".join(lines))

    by_book_lines = []
    by_book_lines.append("李敖人物关系逐本索引")
    by_book_lines.append(f"生成时间：{data['generatedAt']}")
    by_book_lines.append("")
    for book in data["books"]:
        people = "、".join(f"{p['name']}({p['count']})" for p in book["people"][:60])
        by_book_lines.append(
            f"《{book['book']}》｜{book['collection']}｜章节 {book['chapters']}｜人物 {book['personCount']}"
        )
        by_book_lines.append(people if people else "（未抽到候选人物）")
        by_book_lines.append("")
    write_text_lf(export_dir / "by-book-index.txt", "\n".join(by_book_lines))

    with (export_dir / "li-ao-relationships.csv").open("w", newline="", encoding="utf-8-sig") as f:
        writer = csv.writer(f, lineterminator="\n")
        writer.writerow(["姓名", "分类", "主分类", "可信度", "出现次数", "相关出现", "涉及书数", "涉及章节数", "主要书目", "线索"])
        for p in data["people"]:
            writer.writerow(
                [
                    p["name"],
                    " / ".join(p["categoryLabels"]),
                    p["primaryCategoryLabel"],
                    p["confidence"],
                    p["occurrences"],
                    p["relevantOccurrences"],
                    p["bookCount"],
                    p["chapterCount"],
                    "；".join(f"{b['book']}({b['count']})" for b in p["topBooks"][:8]),
                    "、".join(c["cue"] for c in p["cues"][:8]),
                ]
            )


def main() -> None:
    parser = argparse.ArgumentParser(description="Extract Li Ao relationship candidates book by book.")
    parser.add_argument("--source", default=SOURCE_DIR, help="source corpus directory")
    parser.add_argument("--book-path", action="append", help="one book directory under the source corpus; repeat for multiple books")
    parser.add_argument("--all", action="store_true", help="scan the whole corpus explicitly")
    parser.add_argument("--data-dir", default="data", help="output data directory")
    parser.add_argument("--export-dir", default="exports", help="plain-text export directory")
    args = parser.parse_args()

    source_root = Path(args.source).resolve()
    if not source_root.exists():
        raise SystemExit(f"Source directory not found: {source_root}")

    if args.book_path:
        targets = []
        for book_path in args.book_path:
            target = Path(book_path)
            if not target.is_absolute():
                target = Path.cwd() / target
            if not target.exists():
                raise SystemExit(f"Book directory not found: {target}")
            targets.append(target)
        files = sorted(
            (path for target in targets for path in target.rglob("*.txt") if is_content_text_file(path)),
            key=lambda p: str(p),
        )
    elif args.all:
        files = iter_text_files(source_root)
    else:
        sample_books = sorted(
            p for p in source_root.glob("*/*") if p.is_dir()
        )[:12]
        print("请指定一本书，例如：")
        for book in sample_books:
            print(f"  --book-path \"{book}\"")
        print("如确需全库抽取，请显式加 --all。")
        raise SystemExit(2)

    title_names = extract_title_names(source_root, files)
    people: dict[str, PersonHit] = {}
    for idx, path in enumerate(files, 1):
        text = read_text(path)
        extract_from_text(text, path, source_root, people, title_names)
        if idx % 500 == 0:
            print(f"processed {idx}/{len(files)} files; candidates={len(people)}")
    data = build_outputs(people, source_root, files)
    write_json_js(data, Path(args.data_dir))
    write_text_exports(data, Path(args.export_dir))
    print(
        f"done: {data['totals']['people']} people, {data['totals']['books']} books, "
        f"{data['totals']['chapters']} chapters"
    )


if __name__ == "__main__":
    main()
